const crypto = require('crypto');
const headers = items[0].json.headers || {};
const secret = process.env.DAYJOY_WEBHOOK_SECRET;
const signature = headers['x-dayjoy-signature'];
const timestamp = headers['x-dayjoy-timestamp'];
const eventId = headers['x-dayjoy-event-id'];
const eventType = headers['x-dayjoy-event'];
if (!signature || !timestamp || !eventId || !eventType) throw new Error('Missing required headers');
if (Math.abs(Math.floor(Date.now()/1000) - parseInt(timestamp,10)) > 300) throw new Error('Stale timestamp');
const bodyBuffer = await this.helpers.getBinaryDataBuffer(items[0], 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(bodyBuffer).digest('hex');
const sigBuf = Buffer.from(signature), expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) throw new Error('Invalid signature');
const ALLOWED = ['lead.created', 'lead.reassign_requested'];
if (!ALLOWED.includes(eventType)) throw new Error('Unexpected event: ' + eventType);
const payload = JSON.parse(bodyBuffer.toString('utf8'));
payload._meta = { eventId, eventType, receivedAt: new Date().toISOString() };
return [{ json: payload }];

// Classify time-of-day: business hours vs after-hours
const hour = new Date().getHours(); // 0-23, server local time (set n8n TZ=Asia/Kolkata)
const day = new Date().getDay(); // 0=Sun, 6=Sat
const isWeekday = day >= 1 && day <= 6; // Mon-Sat in India standard week
const isBusinessHours = isWeekday && hour >= 9 && hour < 18;
return [{
  json: {
    ...items[0].json,
    _routing: {
      isBusinessHours,
      isAfterHours: !isBusinessHours,
      hour,
      day
    }
  }
}];

// Smart assignment scoring function — used by both branches
// Score each rep: +5 territory match, +3 language match, -1 per active lead (workload balance)
const lead = $('Verify HMAC Signature').item.json;
const reps = ($json.data || $json.reps || []).filter(r => r && r.id);
if (!reps.length) {
  return [{ json: { assignedRepId: null, assignmentReason: 'no_reps_available', leadId: lead.leadId || lead.id, lead } }];
}

const territory = lead.territory || '';
const language = lead.language || 'en';

const scored = reps.map(r => {
  let score = 0;
  const reasons = [];
  if (r.territory && r.territory === territory) { score += 5; reasons.push('territory_match'); }
  if (Array.isArray(r.languages) && r.languages.includes(language)) { score += 3; reasons.push('language_match'); }
  score -= (r.activeLeads || 0); // workload balance
  if (r.lastAssignedAt) {
    const minsSince = (Date.now() - new Date(r.lastAssignedAt).getTime()) / 60000;
    score += Math.min(2, minsSince / 60); // boost reps idle longer
  }
  return { rep: r, score, reasons };
});

scored.sort((a, b) => b.score - a.score);
const winner = scored[0];

return [{
  json: {
    leadId: lead.leadId || lead.id,
    leadFirstName: lead.firstName,
    leadLastName: lead.lastName,
    leadEmail: lead.email,
    leadPhone: lead.phone,
    leadTerritory: territory,
    leadLanguage: language,
    assignedRepId: winner.rep.id,
    assignedRepName: winner.rep.name,
    assignedRepEmail: winner.rep.email,
    assignedRepPhone: winner.rep.phone,
    assignmentReason: winner.reasons.join('+') || 'round_robin',
    assignmentScore: winner.score,
    assignmentWindow: $('Classify Time Window').item.json._routing.isBusinessHours ? 'business_hours' : 'after_hours'
  }
}];
